export function getProductMaster(sku: string): ProductMasterItem | undefined {
  return PRODUCT_MASTER[sku.toUpperCase()];
}

export function getCategoryFromMaster(sku: string): string {
  const item = getProductMaster(sku);
  return item?.category || 'Other';
}

export function getSubcategoryFromMaster(sku: string): string {
  const item = getProductMaster(sku);
  return item?.subcategory || '';
}

export function getProductNameFromMaster(sku: string): string {
  const item = getProductMaster(sku);
  return item?.name || sku;
}
